    academicTipTitle: 'Академический совет дня',
    jordanNoteTitle: 'Заметка от Джордана',
    jordanNotes: [
      "Опять учился до двух ночи... Но это того стоило, лекция наконец-то стала понятна.",
      "Бисквит снова сбросил мои конспекты со стола. Настоящий разбойник, но я всё равно его люблю!",
      "Не забудь выпить кофе перед парой! Сегодня будет длинная лекция.",
      "Ты в последнее время так много занимаешься. Обязательно сделай небольшой перерыв!",
      "Наконец-то разложил все карточки по цветам. Посмотрим, поможет ли это на экзамене!",
      "Видел сегодня, как кто-то заснул на первом ряду. Честно говоря, очень его понимаю.",
      "Если нужно потренироваться перед презентацией, я готов с удовольствием послушать!",
      "На третьем этаже библиотеки сейчас очень тихо, если тебе нужно сосредоточиться.",
      "Мы отлично справимся с этим семестром, я прямо чувствую! Так держать!",
      "Бисквит 20 минут гипнотизировал мой ноутбук. Кажется, он пытается учить английский.",
      "В столовой сегодня свежие тёплые маффины. Зайди взять, пока не разобрали!",
      "Только что закончил черновик эссе! Пальцы отваливаются, но каково же это облегчение.",
      "Если какая-то тема кажется сложной, просто вспомни, какой огромный путь ты уже прошёл.",
      "Видел сегодня закат над кампусом? В такую погоду здесь просто невероятно красиво.",
      "Скажи, если захочешь вечером вместе повторить новые слова по карточкам!",
      "Я купил ещё чая к нам в комнату. Угощайся в любое время, когда засиживаешься за учёбой!"
    ],
    academicTips: [
      'В академических эссе используйте "In addition" или "Furthermore" для введения подтверждающих аргументов в абзаце.',
      'При сопоставлении двух идей используйте плавный переход с помощью "On the other hand" или "In contrast".',
      'Чтобы заявить о четком следствии или результате, отдавайте предпочтение академическим связкам вроде "Therefore" или "Consequently".',
      'Приводя поясняющие примеры на семинаре, вводите их с помощью "For instance" или "To illustrate".',
      'Элегантно структурируйте выводы абзаца, начиная последнее предложение с "In summary" или "To conclude".',
      'Выражайте решительное согласие с опубликованным исследованием, используя фразы вроде "Consistent with" или "In line with".',
      'Признавайте противоположные точки зрения на дискуссионных форумах, начиная с уступок вроде "Admittedly" или "Although".',
      'Если вы хотите прояснить сложное понятие, используйте уточняющие фразы, такие как "In other words" или "Specifically".',
      'Чтобы подчеркнуть критически важный результат в отчете о научной работе, начните с "Indeed" или "Of particular significance".',
      'Избегайте использования разговорной лексики; вместо "get" используйте "obtain", а вместо "bad" — "detrimental".',
      'В аргументированном письме подкрепляйте утверждения, ссылаясь на источники с помощью "According to" или "As stated by".',
      'Структурируйте абзацы с академическим сравнением, используя такие связующие наречия, как "Similarly" или "Correspondingly".',
      'Вводите альтернативные решения или гипотезы в эссе, используя "Alternatively" или "On the other hand".',
      'При анализе данных экспериментальных исследований используйте объективные показатели, такие как "Presumably" или "Evidently", чтобы звучать взвешенно.',
      'Указывайте хронологическую последовательность в своих исторических аргументах с помощью "Subsequently" или "Previously".',
      'Выделяйте логический контраргумент на семинарах, используя такие связки, как "Nevertheless" или "Nonetheless".',
      'Чтобы обобщить второстепенные детали и сосредоточиться на главной тенденции, начните с "On the whole" или "Broadly speaking".',
      'Вводите научные определения в своей работе по лингвистике с помощью "Defined as" или "Refers to".',
      'Чтобы показать, что результат самоочевиден, используйте научные переходы "Needless to say" или "As might be expected".',
      'Выражайте в обзоре литературы предположения, а не уверенность, используя "Suggests that" или "Implies".',
      'В классных презентациях структурируйте части своего выступления, используя логический порядок: "Firstly", "Secondly" и "Finally".',
      'Чтобы ввести условие для научной реакции, используйте академические фразы вроде "Provided that" или "On the condition that".',
      'Выделите главную цель вашего проекта в аннотации, начав с "Primarily" или "Most importantly".',
      'Признавайте ограничения исследований или пробелы в эксперименте в ходе обсуждения с помощью "Admittedly" или "A potential limitation is".',
      'Чтобы представить общий научный консенсус в вашей области, начните с "It is widely accepted that" или "Scholars generally agree that".'
    ],

