    jordanNoteTitle: 'Nota de Jordan',
    jordanNotes: [
      "Volví a estudiar hasta las 2 a.m... pero valió la pena, la clase finalmente tuvo sentido.",
      "Biscuit volvió a tirar mis apuntes del escritorio. Es un peligro, pero igual lo quiero.",
      "¡No olvides tomar un café antes de clase! Hoy la conferencia va a ser larga.",
      "Has estado estudiando mucho últimamente. ¡Asegúrate de tomarte un pequeño descanso!",
      "Al fin organicé mis fichas de estudio por colores. ¡Veamos si ayuda para el examen!",
      "Hoy vi a alguien dormirse en la primera fila de la clase. Sinceramente, me sentí identificado.",
      "Si necesitas a alguien para ensayar tu presentación, ¡estoy listo para escucharte!",
      "El tercer piso de la biblioteca está muy tranquilo ahora por si necesitas concentrarte.",
      "¡Nos va a ir increíble este semestre, lo presiento! Sigue con esa gran energía.",
      "Biscuit se quedó 20 minutos mirando mi laptop. Creo que intenta aprender inglés.",
      "Hay muffins calientes recién hechos en el comedor. ¡Ve por uno antes de que se acaben!",
      "¡Terminé el borrador de mi ensayo! Me duelen los dedos, pero qué alivio haber acabado.",
      "Cuando un capítulo te parezca difícil, recuerda todo lo que ya has avanzado.",
      "¡¿Viste el campus hoy? Con este clima se ve realmente increíble.",
      "¡Avísame si quieres repasar las tarjetas de vocabulario juntos más tarde!",
      "Compré más té para nuestra habitación. ¡Sírvete cuando te quedes estudiando de noche!"
    ],
    academicTips: [
      'En los ensayos académicos, use "In addition" o "Furthermore" para introducir puntos de apoyo en un párrafo.',
      'Al contrastar dos ideas, haga la transición suavemente usando "On the other hand" o "In contrast".',
      'Para declarar una consecuencia o resultado claro, prefiera conectores académicos como "Therefore" o "Consequently".',
      'Al dar ejemplos ilustrativos en un seminario, introdúzcalos con "For instance" o "To illustrate".',
      'Estructure las conclusiones de sus párrafos de manera elegante comenzando la última oración con "In summary" o "To conclude".',
      'Exprese un fuerte acuerdo con las investigaciones publicadas utilizando frases como "Consistent with" o "In line with".',
      'Reconozca los puntos de vista opuestos en los foros de discusión abriendo con concesiones como "Admittedly" o "Although".',
      'Cuando desee aclarar un concepto complejo, use frases aclaratorias como "In other words" o "Specifically".',
      'Para enfatizar un hallazgo crucial en su informe de laboratorio de ciencias, lidere con "Indeed" o "Of particular significance".',
      'Evite el vocabulario coloquial; en lugar de "get", use "obtain", y en lugar de "bad", use "detrimental".',
      'En la escritura argumentativa, apoye sus afirmaciones haciendo referencia a fuentes con "According to" o "As stated by".',
      'Estructure los párrafos de comparación académica utilizando adverbios cohesivos como "Similarly" o "Correspondingly".',
      'Introduzca soluciones o hipótesis alternativas en los ensayos utilizando "Alternatively" o "On the other hand".',
      'Al analizar los datos de una investigación experimental, use calificadores objetivos como "Presumably" o "Evidently" para sonar mesurado.',
      'Indique secuencias cronológicas en sus argumentos históricos utilizando "Subsequently" o "Previously".',
      'Destaque un contraargumento lógico en los seminarios utilizando conectores como "Nevertheless" o "Nonetheless".',
      'Para resumir detalles menores y enfocarse en la tendencia principal, lidere con "On the whole" o "Broadly speaking".',
      'Introduzca definiciones académicas en su artículo de lingüística con "Defined as" o "Refers to".',
      'Para demostrar que un resultado es evidente por sí mismo, use las transiciones eruditas "Needless to say" o "As might be expected".',
      'Exprese sugerencias tentativas en lugar de certezas en su revisión de literatura con "Suggests that" o "Implies".',
      'En las presentaciones de clase, estructure las partes de su discurso utilizando un orden lógico: "Firstly", "Secondly" y "Finally".',
      'Para introducir una condición para una reacción científica, use frases académicas como "Provided that" o "On the condition that".',
      'Destaque el objetivo principal de su proyecto en el resumen comenzando con "Primarily" o "Most importantly".',
      'Reconozca las limitaciones de la investigación o las brechas experimentales en su discusión con "Admittedly" o "A potential limitation is".',
      'Para presentar el consenso académico general en su campo, lidere con "It is widely accepted that" o "Scholars generally agree that".'
    ],

