    academicTipTitle: 'Akademischer Tipp des Tages',
    jordanNoteTitle: 'Jordans Notiz',
    jordanNotes: [
      "Wieder bis 2 Uhr nachts gelernt... aber es hat sich gelohnt, die Vorlesung hat endlich Klick gemacht.",
      "Biscuit hat wieder meine Notizen vom Schreibtisch geworfen. Ein kleiner Racker, aber ich liebe ihn trotzdem.",
      "Vergiss nicht, vor der Vorlesung einen Kaffee zu holen! Heute wird es lang.",
      "Du hast in letzter Zeit so viel gelernt. Mach unbedingt eine kleine Pause!",
      "Ich habe endlich meine Lernkarten nach Farben sortiert. Mal sehen, ob es für die Prüfung hilft!",
      "Habe heute jemanden in der ersten Reihe einschlafen sehen. Ehrlich gesagt, sehr verständlich.",
      "Wenn du jemanden zum Üben deiner Präsentation brauchst, höre ich dir gerne zu!",
      "Der dritte Stock der Bibliothek ist gerade super ruhig, falls du dich konzentrieren musst.",
      "Wir werden dieses Semester rocken, ich spüre es! Behalte diese tolle Energie bei.",
      "Biscuit hat 20 Minuten lang auf meinen Laptop gestarrt. Ich glaube, er versucht Englisch zu lernen.",
      "In der Mensa gibt es heute frische warme Muffins. Hol dir einen, bevor alle weg sind!",
      "Gerade meinen Essay-Entwurf fertiggestellt! Meine Finger sind taub, aber es fühlt sich großartig an.",
      "Wenn ein Kapitel schwer erscheint, denk einfach daran, wie viel du schon erreicht hast.",
      "Hast du den Campus heute gesehen? Bei diesem Wetter sieht er wirklich fantastisch aus.",
      "Sag Bescheid, wenn du später zusammen Vokabeln wiederholen möchtest!",
      "Ich habe extra Tee für unser Wohnheimzimmer besorgt. Bedien dich ruhig, wenn du lange lernst!"
    ],
    academicTips: [
      'Verwenden Sie in akademischen Aufsätzen "In addition" oder "Furthermore", um unterstützende Punkte in einem Absatz einzuführen.',
      'Verwenden Sie beim Gegenüberstellen zweier Ideen einen fließenden Übergang mit "On the other hand" oder "In contrast".',
      'Um eine klare Konsequenz oder ein Ergebnis anzugeben, bevorzugen Sie akademische Konnektoren wie "Therefore" oder "Consequently".',
      'Wenn Sie in einem Seminar illustrative Beispiele nennen, führen Sie diese mit "For instance" oder "To illustrate" ein.',
      'Strukturieren Sie Ihre Absatzschlüsse elegant, indem Sie den letzten Satz mit "In summary" oder "To conclude" beginnen.',
      'Drücken Sie starke Übereinstimmung mit veröffentlichter Forschung aus, indem Sie Ausdrücke wie "Consistent with" oder "In line with" verwenden.',
      'Erkennen Sie gegensätzliche Standpunkte in Diskussionsforen an, indem Sie mit Zugeständnissen wie "Admittedly" oder "Although" einleiten.',
      'Wenn Sie ein komplexes Konzept klarstellen möchten, verwenden Sie verdeutlichende Ausdrücke wie "In other words" oder "Specifically".',
      'Um ein entscheidendes Ergebnis in Ihrem wissenschaftlichen Laborbericht hervorzuheben, leiten Sie mit "Indeed" oder "Of particular significance" ein.',
      'Vermeiden Sie umgangssprachlichen Wortschatz; verwenden Sie anstelle von "get" "obtain" und anstelle von "bad" "detrimental".',
      'Stützen Sie in argumentativen Texten Behauptungen, indem Sie auf Quellen mit "According to" oder "As stated by" verweisen.',
      'Strukturieren Sie akademische Vergleichsabsätze mit kohäsiven Adverbien wie "Similarly" oder "Correspondingly".',
      'Führen Sie alternative Lösungen oder Hypothesen in Aufsätzen mit "Alternatively" oder "On the other hand" ein.',
      'Verwenden Sie bei der Analyse experimenteller Forschungsdaten objektive Qualifikatoren wie "Presumably" oder "Evidently", um abgewogen zu klingen.',
      'Geben Sie chronologische Abfolgen in Ihren historischen Argumenten mit "Subsequently" oder "Previously" an.',
      'Heben Sie ein logisches Gegenargument in Seminaren hervor, indem Sie Konnektoren wie "Nevertheless" oder "Nonetheless" verwenden.',
      'Um nebensächliche Details zusammenzufassen und sich auf den Haupttrend zu konzentrieren, leiten Sie mit "On the whole" oder "Broadly speaking" ein.',
      'Führen Sie akademische Definitionen in Ihrer Linguistikarbeit mit "Defined as" oder "Refers to" ein.',
      'Um zu zeigen, dass ein Ergebnis selbstverständlich ist, verwenden Sie die wissenschaftlichen Übergänge "Needless to say" oder "As might be expected".',
      'Drücken Sie in Ihrer Literaturübersicht eher vorsichtige Vorschläge als Gewissheiten mit "Suggests that" oder "Implies" aus.',
      'Strukturieren Sie Ihre Rede in Klassenpräsentationen in logischer Reihenfolge: "Firstly", "Secondly" und "Finally".',
      'Um eine Bedingung für eine wissenschaftliche Reaktion einzuführen, verwenden Sie akademische Ausdrücke wie "Provided that" oder "On the condition that".',
      'Heben Sie das Hauptziel Ihres Projekts im Abstract hervor, indem Sie mit "Primarily" oder "Most importantly" beginnen.',
      'Erkennen Sie Forschungseinschränkungen oder experimentelle Lücken in Ihrer Diskussion mit "Admittedly" oder "A potential limitation is" an.',
      'Um den allgemeinen wissenschaftlichen Konsens in Ihrem Fachgebiet vorzustellen, leiten Sie mit "It is widely accepted that" oder "Scholars generally agree that" ein.'
    ],

