    academicTips: [
      '在学术论文中，使用 "In addition" 或 "Furthermore" 在段落中引入支持论点。',
      '对比两个观点时，使用 "On the other hand" 或 "In contrast" 进行平滑过渡。',
      '为了陈述明确的后果或结果，更倾向于使用学术连接词如 "Therefore" 或 "Consequently"。',
      '在研讨会中给出说明性例子时，使用 "For instance" 或 "To illustrate" 来引入。',
      '通过在最后一句话开头使用 "In summary" 或 "To conclude"，优雅地构建段落结论。',
      '使用 "Consistent with" 或 "In line with" 等短语表达与已发表研究的高度一致。',
      '在讨论板上承认相反观点时，可以使用 "Admittedly" 或 "Although" 等让步词开头。',
      '当你想澄清一个复杂的概念时，使用解释性短语，例如 "In other words" 或 "Specifically"。',
      '为了在科学实验报告中强调一项关键发现，可以用 "Indeed" 或 "Of particular significance" 开头。',
      '避免使用口语词汇；用 "obtain" 代替 "get"，用 "detrimental" 代替 "bad"。',
      '在议论文中，通过使用 "According to" 或 "As stated by" 引用来源来支持论断。',
      '使用 "Similarly" 或 "Correspondingly" 等衔接副词来构建学术对比段落。',
      '在文章中引入备选解决方案或假设时，使用 "Alternatively" 或 "On the other hand"。',
      '在分析实验研究数据时，使用客观修饰词如 "Presumably" 或 "Evidently" 使论述听起来审慎。',
      '在历史论述中，使用 "Subsequent" 或 "Previously" 来表示时间顺序。',
      '在研讨会中强调逻辑上的反驳论点时，可以使用 "Nevertheless" 或 "Nonetheless" 等连接词。',
      '为了总结次要细节并专注于主要趋势，可以用 "On the whole" 或 "Broadly speaking" 开头。',
      '在语言学论文中引入学术定义时，使用 "Defined as" 或 "Refers to"。',
      '为了表明结果不言而喻，使用学术性过渡词 "Needless to say" 或 "As might be expected"。',
      '在文献综述中表达假设性建议而非确定性结论时，使用 "Suggests that" 或 "Implies"。',
      '在课堂演示中，使用逻辑顺序构建演讲部分："Firstly"、"Secondly" 和 "Finally"。',
      '为了引入科学反应的条件，使用学术短语如 "Provided that" 或 "On the condition that"。',
      '在摘要中用 "Primarily" 或 "Most importantly" 开头来突出项目的主要目标。',
      '在讨论中使用 "Admittedly" 或 "A potential limitation is" 来承认研究局限性或实验不足。',
      '为了介绍您所在领域的通用学术共识，可以用 "It is widely accepted that" 或 "Scholars generally agree that" 开头。'
    ],

