    academicTips: [
      '学術論文では、段落内で支持する論点を紹介するために "In addition" または "Furthermore" を使用します。',
      '2つのアイデアを対比させる場合は、"On the other hand" または "In contrast" を使用してスムーズに移行します。',
      '明確な結果や結論を述べるには、"Therefore" や "Consequently" のような学術的接続詞を好んで使用します。',
      'ゼミで例示をする場合は、"For instance" や "To illustrate" を使って紹介します。',
      '最後の文を "In summary" または "To conclude" で始めることで、段落の結論をエレガントに構成します。',
      '公表された研究への強い同意を表すには、"Consistent with" や "In line with" などのフレーズを使用します。',
      'ディスカッションボードで反対の視点を認めるには、"Admittedly" や "Although" などの譲歩表現で始めます。',
      '複雑な概念を明確にしたい場合は、"In other words" や "Specifically" などの明確化フレーズを使用します。',
      '科学実験レポートで極めて重要な発見を強調するには、"Indeed" や "Of particular significance" で始めます。',
      '口語的な語彙は避けてください。"get" の代わりに "obtain" を、"bad" の代わりに "detrimental" を使用します。',
      '論証的な執筆では、"According to" や "As stated by" を使って情報源を参照し、主張を裏付けます。',
      '比較を行う学術的な段落は、"Similarly" や "Correspondingly" などの結合副詞を使って構成します。',
      'エッセイで代替案や仮説を提示する場合は、"Alternatively" または "On the other hand" を使用します。',
      '実験研究データを分析する際は、控えめな表現にするために "Presumably" や "Evidently" などの客観的な修飾語を使用します。',
      '歴史的な議論で時系列の順序を示すには、"Subsequently" や "Previously" を使用します。',
      'ゼミで論理的な反論を強調するには、"Nevertheless" や "Nonetheless" などの接続詞を使用します。',
      '細部を要約して主要な傾向に焦点を当てるには、"On the whole" や "Broadly speaking" で始めます。',
      '言語学の論文で学術的な定義を提示する際は、"Defined as" や "Refers to" を使用します。',
      '結果が自明であることを示すには、学術的な遷移語である "Needless to say" や "As might be expected" を使用します。',
      '文献レビューで確実性ではなく仮定の提案を表現するには、"Suggests that" や "Implies" を使用します。',
      '研究発表では、"Firstly"、"Secondly"、"Finally" などの論理的な順序を使って発表を構成します。',
      '科学反応の条件を提示する際は、"Provided that" や "On the condition that" などの学術的表現を使用します。',
      '要約でプロジェクトの主要な目的を強調するには、"Primarily" や "Most importantly" で始めます。',
      '考察で研究の限界や実験の不備を認める際は、"Admittedly" や "A potential limitation is" を使用します。',
      '分野における一般的な学術的合意を提示するには、"It is widely accepted that" や "Scholars generally agree that" で始めます。'
    ],

