    jordanNotes: [
      "Ho studiato di nuovo fino alle 2 di notte... ma ne è valsa la pena, finalmente ho capito la lezione.",
      "Biscuit ha fatto cadere di nuovo i miei appunti dalla scrivania. Una peste, ma gli voglio bene.",
      "Non dimenticare di prendere un caffè prima della lezione! Oggi sarà lunga.",
      "Stai studiando davvero tanto ultimamente. Assicurati di fare una piccola pausa!",
      "Ho finalmente organizzato le mie carte di studio per colore. Vediamo se aiuta per il parziale!",
      "Oggi ho visto qualcuno addormentarsi in prima fila a lezione. Onestamente, lo capisco perfettamente.",
      "Se hai bisogno di qualcuno con cui provare la tua presentazione, sono qui per ascoltarti!",
      "Il terzo piano della biblioteca è tranquillissimo in questo momento se hai bisogno di concentrarti.",
      "Spaccheremo in questo semestre, me lo sento! Continua così.",
      "Biscuit ha passato 20 minuti a fissare lo schermo del mio laptop. Penso stia cercando di imparare l'inglese.",
      "Stamattina in mensa ci sono muffin caldi appena sfornati. Prendine uno prima che finiscano!",
      "Ho appena finito la prima bozza del saggio! Ho le dita intorpidite, ma che sollievo aver finito.",
      "Ogni volta che un capitolo ti sembra difficile, ricorda quanta strada hai già fatto.",
      "Hai visto il campus oggi? Con questo tempo è davvero fantastico.",
      "Fammi sapere se stasera ti va di ripassare insieme le carte del vocabolario!",
      "Ho preso altro tè per la nostra stanza. Serviti pure ogni volta che studi fino a tardi!"
    ],
    academicTips: [
      'Nei saggi accademici, usa "In addition" o "Furthermore" per introdurre punti a supporto in un paragrafo.',
      'Quando contrasti due idee, passa agevolmente usando "On the other hand" o "In contrast".',
      'Per dichiarare una chiara conseguenza o risultato, preferisci connettori accademici come "Therefore" o "Consequently".',
      'Quando fornisci esempi illustrativi in un seminario, introducili con "For instance" o "To illustrate".',
      'Struttura le conclusioni dei tuoi paragrafi in modo elegante iniziando l\'ultima frase con "In summary" o "To conclude".',
      'Esprimiti in forte accordo con le ricerche pubblicate usando espressioni come "Consistent with" o "In line with".',
      'Riconosci i punti di vista opposti nei forum di discussione aprendo con concessioni come "Admittedly" o "Although".',
      'Quando vuoi chiarire un concetto complesso, usa espressioni di chiarimento come "In other words" o "Specifically".',
      'Per enfatizzare una scoperta cruciale nel tuo rapporto di laboratorio scientifico, inizia con "Indeed" o "Of particular significance".',
      'Evita l\'uso di vocaboli colloquiali; invece di "get", usa "obtain", e invece di "bad", usa "detrimental".',
      'Nella scrittura argomentativa, supporta le affermazioni facendo riferimento alle fonti con "According to" o "As stated by".',
      'Struttura i paragrafi di confronto accademico usando avverbi coesivi come "Similarly" o "Correspondingly".',
      'Introduci soluzioni o ipotesi alternative nei saggi usando "Alternatively" o "On the other hand".',
      'Quando analizzi i dati di una ricerca sperimentale, usa qualificatori oggettivi come "Presumably" o "Evidently" per apparire misurato.',
      'Indica sequenze cronologiche nelle tue argomentazioni storiche usando "Subsequently" o "Previously".',
      'Evidenzia una controargomentazione logica nei seminari usando connettori come "Nevertheless" o "Nonetheless".',
      'Per riassumere dettagli minori e concentrarsi sulla tendenza principale, inizia con "On the whole" o "Broadly speaking".',
      'Introduci definizioni accademiche nel tuo saggio di linguistica con "Defined as" o "Refers to".',
      'Per dimostrare che un risultato è autoevidente, usa le transizioni accademiche "Needless to say" o "As might be expected".',
      'Esprimi suggerimenti provvisori piuttosto que certezze nella tua rassegna della letteratura con "Suggests that" o "Implies".',
      'Nelle presentazioni in classe, struttura le parti del tuo discorso usando un ordine logico: "Firstly", "Secondly" e "Finally".',
      'Per introdurre una condizione per una reazione scientifica, usa espressioni accademiche come "Provided that" o "On the condition that".',
      'Evidenzia l\'obiettivo principale del tuo progetto nell\'abstract iniziando con "Primarily" o "Most importantly".',
      'Riconosci i limiti della ricerca o le lacune sperimentali nella tua discussione con "Admittedly" o "A potential limitation is".',
      'Per introdurre il consenso accademico generale nel tuo campo, inizia con "It is widely accepted that" o "Scholars generally agree that".'
    ],

