    academicTipTitle: '오늘의 학술 팁',
    jordanNoteTitle: '조단의 한마디',
    jordanNotes: [
      "또 새벽 2시까지 공부했네... 그래도 그 강의가 드디어 이해돼서 다행이야!",
      "비스킷이 또 책상 위에서 내 노트를 떨어뜨렸어. 장난꾸러기지만 미워할 수가 없네.",
      "수업 시작하기 전에 커피 챙기는 거 잊지 마! 오늘 강의 길어질 것 같거든.",
      "요즘 공부 정말 열심히 하더라. 중간중간 꼭 휴식도 취해!",
      "단어 카드를 드디어 색깔별로 정리했어. 중간고사에 도움이 될지 보자고!",
      "오늘 강의 맨 앞줄에서 조는 사람을 봤는데, 솔직히 너무 공감되더라.",
      "발표 연습 상대가 필요하면 언제든 말해, 들어줄게!",
      "집중해서 공부해야 한다면 지금 도서관 3층이 정말 조용하고 좋아.",
      "이번 학기 정말 잘 해낼 것 같은 예감이 들어! 이대로 화이팅하자.",
      "비스킷이 20분 동안 내 노트북 화면을 지켜보더라고. 영어 공부라도 하려는 걸까?",
      "오늘 아침 학식에 갓 구운 따뜻한 머핀이 나왔어. 떨어지기 전에 얼른 가봐!",
      "에세이 초안 드디어 끝냈다! 손가락이 얼얼하지만 다 써서 너무 가뿐해.",
      "어떤 챕터가 어렵게 느껴질 땐, 지금까지 이미 얼마나 많이 성장했는지 떠올려봐.",
      "오늘 캠퍼스 풍경 봤어? 이런 날씨에는 캠퍼스가 정말 멋져 보여.",
      "오늘 밤에 같이 단어 카드 복습하고 싶으면 언제든 알려줘!",
      "우리 기숙사 방에 마실 차를 많이 사뒀어. 밤늦게 공부할 때 편하게 마셔!"
    ],
    academicTips: [
      '학술 에세이에서는 단락에 지지하는 의견을 도입할 때 "In addition" 또는 "Furthermore"를 사용하십시오.',
      '두 가지 아이디어를 대조할 때는 "On the other hand" 또는 "In contrast"를 사용하여 부드럽게 전환하십시오.',
      '명확한 결과나 결론을 밝히려면 "Therefore" 또는 "Consequently"와 같은 학술적 연결어를 선호하십시오.',
      '세미나에서 예시를 들 때는 "For instance" 또는 "To illustrate"로 시작하십시오.',
      '마지막 문장을 "In summary" 또는 "To conclude"로 시작하여 단락 결론을 우아하게 구성하십시오.',
      '발표된 연구와의 강력한 일치를 표현하려면 "Consistent with" 또는 "In line with"와 같은 문구를 사용하십시오.',
      '토론판에서 반대 관점을 인정할 때는 "Admittedly" 또는 "Although"와 같은 양보 표현으로 시작하십시오.',
      '복잡한 개념을 명확히 하고 싶을 때는 "In other words" 또는 "Specifically"와 같은 명확화 문구를 사용하십시오.',
      '과학 실험 보고서에서 중요한 발견을 강조하려면 "Indeed" 또는 "Of particular significance"로 시작하십시오.',
      '구어체 어휘를 피하십시오. "get" 대신 "obtain"을, "bad" 대신 "detrimental"을 사용하십시오.',
      '논증적 글쓰기에서는 "According to" 또는 "As stated by"를 사용하여 출처를 언급함으로써 주장을 뒷받침하십시오.',
      '학술적 비교 단락을 구성할 때는 "Similarly" 또는 "Correspondingly"와 같은 결합 부사를 사용하십시오.',
      '에세이에서 대안적 해결책이나 가설을 도입할 때는 "Alternatively" 또는 "On the other hand"를 사용하십시오.',
      '실험 연구 데이터를 분석할 때는 신중하게 표현하기 위해 "Presumably" 또는 "Evidently"와 같은 객관적 수식어를 사용하십시오.',
      '역사적 논증에서 시간적 순서를 나타낼 때는 "Subsequently" 또는 "Previously"를 사용하십시오.',
      '세미나에서 논리적 반론을 강조하려면 "Nevertheless" 또는 "Nonetheless"와 같은 연결어를 사용하십시오.',
      '지엽적인 세부 사항을 요약하고 주요 경향에 집중하려면 "On the whole" 또는 "Broadly speaking"으로 시작하십시오.',
      '언어학 논문에서 학술적 정의를 도입할 때는 "Defined as" 또는 "Refers to"를 사용하십시오.',
      '결과가 자명하다는 것을 보여주려면 학술적 전이구인 "Needless to say" 또는 "As might be expected"를 사용하십시오.',
      '문헌 고찰에서 확실성보다는 잠정적인 제안을 표현하려면 "Suggests that" or "Implies"를 사용하십시오.',
      '수업 발표에서는 "Firstly", "Secondly", "Finally"와 같은 논리적 순서를 사용하여 발표 내용을 구성하십시오.',
      '과학적 반응의 조건을 도입할 때는 "Provided that" 또는 "On the condition that"과 같은 학술적 문구를 사용하십시오.',
      '초록에서 프로젝트의 주된 목표를 강조하려면 "Primarily" 또는 "Most importantly"로 시작하십시오.',
      '토의에서 연구의 한계나 실험적 공백을 인정할 때는 "Admittedly" 또는 "A potential limitation is"를 사용하십시오.',
      '해당 분야의 일반적인 학술적 합의를 소개하려면 "It is widely accepted that" 또는 "Scholars generally agree that"으로 시작하십시오.'
    ],

